<?php
namespace Tests\Feature\Admin;
use App\Models\Category;use App\Models\Color;use App\Models\Coupon;use App\Models\Order;use App\Models\OrderItem;use App\Models\Product;use App\Models\ProductVariant;use App\Models\ShippingZone;use App\Models\Size;use App\Models\User;use App\Services\AdminMetricsService;use App\Services\CartService;use App\Services\OrderService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;use Tests\TestCase;
class Phase6AdminTest extends TestCase
{
 use RefreshDatabase;private int $n=0;
 private function user(string $role='customer',string $status='active'):User{return User::factory()->create(['role'=>$role,'status'=>$status]);}private function admin():User{return $this->user('admin');}
 private function order(string $status='pending',float $total=500000,?User $u=null):Order{$this->n++;return Order::create(['user_id'=>($u??$this->user())->id,'order_code'=>'ORD20260826'.str_pad((string)$this->n,8,'0',STR_PAD_LEFT),'checkout_token'=>fake()->uuid(),'recipient_name'=>'Customer '.$this->n,'email'=>'customer'.$this->n.'@example.com','phone'=>'0900'.$this->n,'province'=>'HCM','district'=>'1','ward'=>'A','address'=>'Street','subtotal'=>$total,'discount'=>0,'shipping_fee'=>0,'total'=>$total,'status'=>$status]);}
 private function variant(int $stock=5):ProductVariant{$this->n++;$c=Category::create(['name'=>'C'.$this->n,'slug'=>'c'.$this->n,'status'=>'active']);$p=Product::create(['category_id'=>$c->id,'name'=>'Product '.$this->n,'slug'=>'p'.$this->n,'sku'=>'P'.$this->n,'price'=>100000,'status'=>'active']);$co=Color::create(['name'=>'N'.$this->n,'hex_code'=>'#112233','status'=>'active']);$s=Size::create(['name'=>'S'.$this->n,'status'=>'active']);return $p->variants()->create(['color_id'=>$co->id,'size_id'=>$s->id,'sku'=>'V'.$this->n,'stock'=>$stock]);}
 private function placed(?User $u=null,int $stock=5,int $qty=2,?Coupon $coupon=null):array{$u??=$this->user();$v=$this->variant($stock);$z=ShippingZone::create(['name'=>'Z'.$this->n,'code'=>'Z'.$this->n,'status'=>'active']);$z->rates()->create(['name'=>'Std','fee'=>0,'status'=>'active']);app(CartService::class)->add($u,$v,$qty);$o=app(OrderService::class)->placeOrder($u,['recipient_name'=>'A','email'=>'a@a.com','phone'=>'1','province'=>'P','district'=>'D','ward'=>'W','address'=>'A'],fake()->uuid(),$coupon?->code,$z->id);return [$o,$v,$u];}
 public function test_admin_orders_page_200():void{$this->actingAs($this->admin())->get('/admin/orders')->assertOk();}
 public function test_customer_blocked_admin_orders():void{$this->actingAs($this->user())->get('/admin/orders')->assertForbidden();}
 public function test_admin_order_detail():void{$o=$this->order();$this->actingAs($this->admin())->get('/admin/orders/'.$o->id)->assertOk()->assertSee($o->order_code);}
 public function test_pending_to_confirmed():void{$o=$this->order();app(OrderService::class)->transitionByAdmin($this->admin(),$o,'confirmed');$this->assertSame('confirmed',$o->fresh()->status);}
 public function test_confirmed_to_packing():void{$o=$this->order('confirmed');app(OrderService::class)->transitionByAdmin($this->admin(),$o,'packing');$this->assertSame('packing',$o->fresh()->status);}
 public function test_packing_to_shipping():void{$o=$this->order('packing');app(OrderService::class)->transitionByAdmin($this->admin(),$o,'shipping');$this->assertSame('shipping',$o->fresh()->status);}
 public function test_shipping_to_completed():void{$o=$this->order('shipping');app(OrderService::class)->transitionByAdmin($this->admin(),$o,'completed');$this->assertSame('completed',$o->fresh()->status);}
 public function test_invalid_transition_rejected():void{$this->expectException(ValidationException::class);app(OrderService::class)->transitionByAdmin($this->admin(),$this->order(),'shipping');}
 public function test_completed_cannot_cancel():void{$this->expectException(ValidationException::class);app(OrderService::class)->cancelByAdmin($this->admin(),$this->order('completed'),'No');}
 public function test_cancel_pending_restores_stock_once():void{[$o,$v]=$this->placed();app(OrderService::class)->cancelByAdmin($this->admin(),$o,'Admin cancel');$this->assertEquals(5,$v->fresh()->stock);}
 public function test_cancel_confirmed_restores_stock_once():void{[$o,$v]=$this->placed();$a=$this->admin();app(OrderService::class)->transitionByAdmin($a,$o,'confirmed');app(OrderService::class)->cancelByAdmin($a,$o,'Admin cancel');$this->assertEquals(5,$v->fresh()->stock);}
 public function test_double_cancel_safe():void{[$o,$v]=$this->placed();$s=app(OrderService::class);$a=$this->admin();$s->cancelByAdmin($a,$o,'One');try{$s->cancelByAdmin($a,$o,'Two');}catch(ValidationException){}$this->assertEquals(5,$v->fresh()->stock);}
 public function test_coupon_usage_restored_once():void{$c=Coupon::create(['code'=>'SAVE','type'=>'fixed','value'=>1000,'minimum_order'=>0,'status'=>'active']);[$o]=$this->placed(null,5,1,$c);app(OrderService::class)->cancelByAdmin($this->admin(),$o,'Cancel');$this->assertEquals(0,$c->fresh()->used_count);$this->assertDatabaseMissing('coupon_usages',['order_id'=>$o->id]);}
 public function test_status_log_created():void{$o=$this->order();$a=$this->admin();app(OrderService::class)->transitionByAdmin($a,$o,'confirmed','Checked');$this->assertDatabaseHas('order_status_logs',['order_id'=>$o->id,'from_status'=>'pending','to_status'=>'confirmed','changed_by'=>$a->id]);}
 public function test_customers_list_only_customer_role():void{$c=$this->user();$a=$this->admin();$this->actingAs($a)->get('/admin/customers')->assertSee($c->email)->assertDontSee($a->email);}
 public function test_admin_lock_customer():void{$c=$this->user();$this->actingAs($this->admin())->patch('/admin/customers/'.$c->id.'/status',['status'=>'locked']);$this->assertSame('locked',$c->fresh()->status);}
 public function test_admin_unlock_customer():void{$c=$this->user('customer','locked');$this->actingAs($this->admin())->patch('/admin/customers/'.$c->id.'/status',['status'=>'active']);$this->assertSame('active',$c->fresh()->status);}
 public function test_customer_blocked_admin_customers():void{$this->actingAs($this->user())->get('/admin/customers')->assertForbidden();}
 public function test_dashboard_uses_real_data():void{$this->order('completed',123456);$this->actingAs($this->admin())->get('/admin/dashboard')->assertOk()->assertSee('123.456');}
 public function test_revenue_only_completed():void{$this->order('completed',100000);$this->order('pending',900000);$this->assertEquals(100000,app(AdminMetricsService::class)->overview()['totalRevenue']);}
 public function test_cancelled_excluded_revenue():void{$this->order('completed',100000);$this->order('cancelled',800000);$this->assertEquals(100000,app(AdminMetricsService::class)->overview()['totalRevenue']);}
 public function test_top_products_completed_only():void{$a=$this->order('completed');$b=$this->order('cancelled');OrderItem::create(['order_id'=>$a->id,'product_name'=>'Winner','product_sku'=>'WIN','color_name'=>'N','size_name'=>'M','price'=>100,'quantity'=>2,'subtotal'=>200]);OrderItem::create(['order_id'=>$b->id,'product_name'=>'Loser','product_sku'=>'LOSE','color_name'=>'N','size_name'=>'M','price'=>100,'quantity'=>99,'subtotal'=>9900]);$top=app(AdminMetricsService::class)->topProducts();$this->assertSame('WIN',$top->first()->product_sku);$this->assertCount(1,$top);}
 public function test_low_stock_correct():void{$low=$this->variant(2);$this->variant(20);$ids=app(AdminMetricsService::class)->lowStock()->pluck('id');$this->assertTrue($ids->contains($low->id));$this->assertCount(1,$ids);}
 public function test_reports_page_200():void{$this->actingAs($this->admin())->get('/admin/reports')->assertOk();}
 public function test_order_search_and_filter_works():void{$wanted=$this->order('shipping');$other=$this->order('pending');$this->actingAs($this->admin())->get('/admin/orders?q='.$wanted->order_code.'&status=shipping')->assertSee($wanted->order_code)->assertDontSee($other->order_code);}
}
